  });
  const oldHandled = new Promise<void>((resolve) => {
    finishOld = resolve;
  });
  await backend.route("**/api/search?*", async (route) => {
    const term = new URL(route.request().url()).searchParams.get("term");
    if (term === "John") await oldResponse;
